parameters.jsCode:
const o = $input.first().json;
if (!o.order_id) {
  const id = $('Bestellnummer übernehmen').first().json.order_id;
  throw new Error(`Bestellung '${id ?? ''}' nicht in der Datenbank gefunden`);
}
const items = Array.isArray(o.items_json)
  ? o.items_json
  : JSON.parse(o.items_json ?? '[]');

// Digitale Artikel verkauft Etsy als Plattform selbst an den Käufer
// (Art. 9a MwSt-DVO). Sie werden monatlich per Reverse-Charge-Rechnung an
// Etsy abgerechnet (Workflow 05) und gehören nicht auf die Kundenrechnung –
// sonst stünde derselbe Umsatz zweimal in den Büchern.
const physical = items.filter(it => !it.is_digital);
if (!physical.length) {
  throw new Error(`Bestellung ${o.order_id} enthält nur digitale Artikel – diese werden über die `
    + `monatliche Reverse-Charge-Rechnung an Etsy abgerechnet (Workflow 05), nicht an den Käufer`);
}

if (!o.invoice_number) {
  throw new Error(`Bestellung ${o.order_id} hat keine Rechnungsnummer`);
}

// Seller-Stammdaten kommen aus app_config (scope 'seller'), siehe README §5.
// Nicht hier im Code pflegen: ein Re-Import des Workflows würde echte Daten
// sonst wieder durch Platzhalter (Muster-IBAN, Muster-Steuernummer) ersetzen.
const cfg = o.seller_config ?? {};
const missing = ['name', 'street', 'zip', 'city'].filter(k => !cfg[k]);
if (missing.length) {
  throw new Error(`Verkäuferdaten fehlen in app_config (scope 'seller'): ${missing.join(', ')}`);
}
// Absender/Empfänger der PDF-Mail ebenfalls aus app_config (scope 'mail')
const mail = o.mail_config ?? {};
if (!mail.from || !mail.to) {
  throw new Error("Mail-Adressen fehlen in app_config (scope 'mail'): from, to");
}

const SELLER = {
  name:             cfg.name,
  business_name:    cfg.business_name ?? null,
  tagline:          cfg.tagline ?? null,
  street:           cfg.street,
  zip:              cfg.zip,
  city:             cfg.city,
  country:          cfg.country ?? null,
  email:            cfg.email ?? null,
  phone:            cfg.phone ?? null,
  website:          cfg.website ?? null,
  iban:             cfg.iban ?? null,
  bank_name:        cfg.bank_name ?? null,
  tax_id:           cfg.tax_id ?? null,
  vat_id:           cfg.vat_id ?? null,
  kleinunternehmer: String(cfg.kleinunternehmer ?? 'true').toLowerCase() !== 'false',
};

// Etsy liefert Titel HTML-kodiert (&#39;, &quot;, &amp;) – ältere DB-Zeilen
// enthalten das noch, daher hier ebenfalls dekodieren.
const decodeHtml = (s) => s == null ? s : String(s)
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&');

// NUMERIC-Spalten kommen aus Postgres als String ("12.50")
const round2 = (n) => Math.round(Number(n) * 100) / 100;

const lineTotal = (it) => round2(Number(it.price) * Number(it.quantity));

// Artikel für API formatieren (nur physische, s.o.)
const lineItems = physical.map((it, i) => ({
  pos:         i + 1,
  description: decodeHtml(it.title) ?? 'Artikel',
  quantity:    Number(it.quantity),
  unit_price:  Number(it.price),
  total:       lineTotal(it),
}));

// Etsy-Gutscheine stecken nur in receipt.subtotal (= Artikelsumme − Rabatt).
// Rabatt anteilig verteilen (bei gemischten Bestellungen entfällt der Rest auf
// die digitalen Artikel, Workflow 05 rechnet identisch) und als Rabattzeile
// ausweisen, sonst geht die Rechnung nicht auf.
const allSum       = round2(items.reduce((sum, it) => sum + lineTotal(it), 0));
const factor       = o.subtotal != null && allSum > 0 ? Number(o.subtotal) / allSum : 1;
const itemsSum     = round2(lineItems.reduce((sum, it) => sum + it.total, 0));
const subtotal     = round2(itemsSum * factor);
const shippingCost = round2(o.shipping_cost ?? 0);
const discount     = Math.max(0, round2(itemsSum - subtotal));

const buyer = {
  name:    o.buyer_name ?? '',
  street:  o.buyer_street,
  zip:     o.buyer_zip,
  city:    o.buyer_city,
  country: o.buyer_country,
};

// Kalenderdatum in deutscher Zeit – n8n läuft meist in UTC, sonst rutschen
// Bestellungen zwischen 0 und 2 Uhr auf den Vortag.
const invoiceDate = new Date(o.order_date).toLocaleDateString('de-DE', {
  day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'Europe/Berlin',
});

return {
  json: {
    // Rechnungsrequest
    invoice_request: {
      invoice_number: o.invoice_number,
      invoice_date:   invoiceDate,
      order_id:       o.order_id,
      seller:         SELLER,
      buyer,
      items:          lineItems,
      subtotal,
      shipping_cost:  shippingCost,
      discount,
      total:          round2(subtotal + shippingCost),
      currency:       o.currency ?? 'EUR',
      payment_note:   "Bereits bezahlt via Etsy Payments",
    },
    // Lieferscheinrequest
    delivery_request: {
      delivery_number: "LS-" + o.invoice_number,
      date:            invoiceDate,
      order_id:        o.order_id,
      seller:          SELLER,
      buyer,
      items:           lineItems,
      tracking_number: o.tracking_number,
      carrier:         o.carrier,
    },
    order_id: o.order_id,
    mail:     { from: mail.from, to: mail.to },
  }
};

// Binary-Anhaenge explizit von beiden Branches einsammeln.
// Die Merge-Node (combineByPosition) verschmilzt zuverlaessig nur json,
// nicht zwingend beide binary-Properties.
// .first() statt .item: Ein Webhook-Aufruf = genau ein Item, und so muss
// n8n keine Paired-Item-Kette durch die Merge-Node aufloesen.
return [{
  json: $('Request-Bodies aufbauen').first().json,
  binary: {
    invoice_pdf:  $('Rechnung generieren').first().binary.invoice_pdf,
    delivery_pdf: $('Lieferschein generieren').first().binary.delivery_pdf,
  },
}];

parameters.query:
UPDATE orders
SET invoice_path = '/pdfs/Rechnung_' || $1 || '.pdf'
WHERE order_id = $1;

