// Antwort für den Webhook (Webhook antwortet mit dem letzten Node).
// Einen 'Respond to Webhook'-Node erlaubt n8n neben einem Formular nicht.
const a = $('Anhaenge zusammenstellen').first().json;
return [{ json: { status: 'ok', order_id: a.order_id, invoice_number: a.invoice_request.invoice_number } }];

// Formular und Webhook liefern die Bestellnummer an unterschiedlicher Stelle.
const fromForm = $('Formular: Bestellnummer').isExecuted;
const raw = fromForm
  ? $('Formular: Bestellnummer').first().json['Bestellnummer']
  : $('Webhook: Order-ID empfangen').first().json.body?.order_id;
const order_id = String(raw ?? '').trim();
if (!order_id) throw new Error('Keine Bestellnummer angegeben');
return [{ json: { order_id, from_form: fromForm } }];

// Die Postgres-Node davor gibt keine Binärdaten weiter → PDFs wieder anhängen
const a = $('Anhaenge zusammenstellen').first();
return [{ json: { invoice_number: a.json.invoice_request.invoice_number, order_id: a.json.order_id,
                  mail_to: a.json.mail.to }, binary: a.binary }];
